import React, { useState } from "react";
import styled from "styled-components";

const PageContainer = styled.div`
  font-family: Arial, sans-serif;
  display: flex;
  flex-direction: column;
  background-color: #f9f9f9;
  height: 100vh;
  padding: 20px;
`;

const HeaderBar = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
`;

const Content = styled.div`
  display: flex;
  margin-top: 20px;
  gap: 20px;
`;

const Sidebar = styled.aside`
  width: 200px;
  background-color: #ffffff;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  padding: 20px;
`;

const SidebarItem = styled.li`
  list-style: none;
  padding: 10px;
  margin-bottom: 10px;
  border-radius: 5px;
  cursor: pointer;
  background-color: ${(props) => (props.active ? "#007bff" : "#f1f1f1")};
  color: ${(props) => (props.active ? "white" : "black")};
  &:hover {
    background-color: #007bff;
    color: white;
  }
`;

const AddButton = styled.button`
  margin-top: 20px;
  width: 100%;
  padding: 10px;
  background-color: #28a745;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-weight: bold;
  &:hover {
    background-color: #218838;
  }
`;

const EmployeeList = styled.div`
  width: 300px;
`;

const EmployeeInfo = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 20px;
`;

const Card = styled.div`
  background-color: white;
  border-radius: 5px;
  padding: 20px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
`;

const Row = styled.div`
  display: flex;
  gap: 20px;
`;

const EmployeePage = ({ vehicleRegistration, ownerName, ownerPhone, managerName }) => {
  const [selectedRole, setSelectedRole] = useState("driver");
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [employees, setEmployees] = useState({
    driver: [],
    driller: [],
    manager: [],
    worker: [],
  });

  const handleRoleClick = (role) => {
    setSelectedRole(role);
    setSelectedEmployee(null);
  };

  const handleEmployeeClick = (employee) => {
    setSelectedEmployee(employee);
  };

  const handleAddEmployee = () => {
    const newEmployee = {
      id: Date.now(),
      name: "",
      phone: "",
      fixedSalary: "",
      expense: "0",
      earnedMoney: "0",
      remainingAmount: "0",
      daysWorked: 0,
    };
    setEmployees((prev) => ({
      ...prev,
      [selectedRole]: [...prev[selectedRole], newEmployee],
    }));
    setSelectedEmployee(newEmployee);
  };

  const handleUpdateEmployee = (field, value) => {
    setSelectedEmployee((prev) => ({ ...prev, [field]: value }));
    setEmployees((prev) => ({
      ...prev,
      [selectedRole]: prev[selectedRole].map((emp) =>
        emp.id === selectedEmployee.id ? { ...emp, [field]: value } : emp
      ),
    }));
  };

  return (
    <PageContainer>
      <HeaderBar>
        <div>Vehicle Registration: {vehicleRegistration}</div>
        <div>Owner: {ownerName} | Phone: {ownerPhone}</div>
        <div>Manager: {managerName}</div>
      </HeaderBar>

      <Content>
        <Sidebar>
          <ul>
            {Object.keys(employees).map((role) => (
              <SidebarItem
                key={role}
                active={selectedRole === role}
                onClick={() => handleRoleClick(role)}
              >
                {role.charAt(0).toUpperCase() + role.slice(1)}
              </SidebarItem>
            ))}
          </ul>
          <AddButton onClick={handleAddEmployee}>Add Employee</AddButton>
        </Sidebar>

        <EmployeeList>
          <h3>{selectedRole.charAt(0).toUpperCase() + selectedRole.slice(1)}s</h3>
          <ul>
            {employees[selectedRole].map((employee) => (
              <SidebarItem
                key={employee.id}
                active={selectedEmployee?.id === employee.id}
                onClick={() => handleEmployeeClick(employee)}
              >
                {employee.name || "New Employee"}
              </SidebarItem>
            ))}
          </ul>
        </EmployeeList>

        {selectedEmployee && (
          <EmployeeInfo>
            <Row>
              <Card>
                <h3>Name</h3>
                <input
                  type="text"
                  value={selectedEmployee.name}
                  onChange={(e) => handleUpdateEmployee("name", e.target.value)}
                />
              </Card>
              <Card>
                <h3>Phone Number</h3>
                <input
                  type="text"
                  value={selectedEmployee.phone}
                  onChange={(e) => handleUpdateEmployee("phone", e.target.value)}
                />
              </Card>
              <Card>
                <h3>Fixed Salary</h3>
                <input
                  type="text"
                  value={selectedEmployee.fixedSalary}
                  onChange={(e) => handleUpdateEmployee("fixedSalary", e.target.value)}
                />
              </Card>
            </Row>

            <Row>
              <Card>
                <h3>Expense</h3>
                <input
                  type="text"
                  value={selectedEmployee.expense}
                  onChange={(e) => handleUpdateEmployee("expense", e.target.value)}
                />
              </Card>
              <Card>
                <h3>Earned Money</h3>
                <input
                  type="text"
                  value={selectedEmployee.earnedMoney}
                  onChange={(e) => handleUpdateEmployee("earnedMoney", e.target.value)}
                />
              </Card>
              <Card>
                <h3>Remaining Amount</h3>
                <input
                  type="text"
                  value={selectedEmployee.remainingAmount}
                  onChange={(e) => handleUpdateEmployee("remainingAmount", e.target.value)}
                />
              </Card>
            </Row>

            <Row>
              <Card>
                <h3>Days Worked</h3>
                <input
                  type="number"
                  value={selectedEmployee.daysWorked}
                  onChange={(e) => handleUpdateEmployee("daysWorked", e.target.value)}
                />
              </Card>
            </Row>
          </EmployeeInfo>
        )}
      </Content>
    </PageContainer>
  );
};

export default EmployeePage;
